// Two variable definitions
const concArray = [0.100, 0.125, 0.150, 0.175, 0.2, 0.225, 0.250, 0.275, 0.3];
const concIndex = OLI.random(0,8);
const conc = concArray[concIndex] .toPrecision(3);
const pH = OLI.random(1.8,3.5,2);
const H = 10**-pH;
const Hsf = H .toPrecision(3);
const concHA = (conc-H) .toPrecision(3);

const ka = ((H*H)/concHA);
const karound = ka .toPrecision(3);
const kasf = ((Hsf*Hsf)/concHA) .toPrecision(2);
const kalow = 0.98*ka .toPrecision(2);
const kahigh = 1.02*ka .toPrecision(2);
const err = (karound - kasf)*100/karound;

const diss = (H/conc*100) .toPrecision(2);
const disslow = diss*0.98;
const disshigh= diss*1.02;

// Expose variables to OLI
module.exports = {
  concIndex, conc, pH, H, Hsf, concHA, ka, karound, kasf, err, kalow, kalow, kahigh, diss, disslow, disshigh
};
